from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]; C=json.loads((ROOT/'profile.json').read_text()); OUT=ROOT/'generated/info-card.svg'; t=C['theme']; W,H=650,320
rows=[('user',C['name']),('role',C['headline']),('location',C['location']),('experience',C['experience']),('github',C['github_username']),('stack',' · '.join(C['stack']))]
rs=''.join(f'<text x="32" y="{88+i*35}" class="key">{html.escape(k)}</text><text x="145" y="{88+i*35}" class="value">{html.escape(v)}</text>' for i,(k,v) in enumerate(rows))
links='   '.join(v for v in C.get('social',{}).values() if v)
svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}"><style>.bg{{fill:{t['panel']}}}.frame{{fill:none;stroke:{t['muted']};opacity:.55}}.title{{font:600 12px monospace;fill:{t['accent']}}}.prompt{{font:11px monospace;fill:{t['muted']}}}.key{{font:600 11px monospace;fill:{t['accent']}}}.value{{font:11px monospace;fill:{t['text']}}}.links{{font:8px monospace;fill:{t['muted']}}}.cursor{{fill:{t['accent']};animation:blink 1s steps(2) infinite}}@keyframes blink{{50%{{opacity:0}}}}@media(prefers-reduced-motion:reduce){{.cursor{{animation:none}}}}</style><rect class="bg" width="100%" height="100%" rx="8"/><rect class="frame" x=".5" y=".5" width="{W-1}" height="{H-1}" rx="8"/><text x="32" y="30" class="title">╭─ system information</text><text x="32" y="51" class="prompt">$ whoami</text><text x="90" y="51" class="value">{html.escape(C['name'])}</text><rect x="207" y="42" width="7" height="12" class="cursor"/><line x1="32" y1="65" x2="{W-32}" y2="65" stroke="{t['grid']}"/>{rs}<line x1="32" y1="286" x2="{W-32}" y2="286" stroke="{t['grid']}"/><text x="32" y="305" class="links">{html.escape(links[:105])}</text></svg>'''
OUT.parent.mkdir(exist_ok=True); OUT.write_text(svg); print(f'Wrote {OUT}')
